svg.script:
"use strict";
var SVG_NS = "http://www.w3.org/2000/svg";
var TOKEN = function (name) { return "{" + name + "}"; };

var BUILTIN = {
    contestType: "ICPC",
    hideHashtag: false,
    hideSite: false,
    finals: { include: true, includeEmpty: false },
    fontColor: "#FFFFFF",
    mainColor: "#548DE3",
    logoExtension: "svg+xml",
    logo: "",
    background: ""
};

var BUILTIN_TEAM = {
    id: "sample",
    university: {
        fullName: "Sample University of Technology",
        shortName: "SUT",
        region: "Sample Region",
        hashTag: "#SAMPLE",
        appYears: [2018, 2019, 2021, 2022, 2023, 2024],
        winYears: [2022, 2024],
        goldYears: [2021, 2022, 2024],
        silverYears: [2019],
        bronzeYears: [2018],
        regYears: [2018, 2019, 2021]
    },
    team: { name: "Sample Team", regionals: ["3rd place, Sample Regional 2025"] },
    coach: {
        name: "Sample Coach",
        cfRating: 2401,
        achievements: [
            { achievement: "ICPC World Finals Bronze Medalist (2008)", priority: 100 },
            { achievement: "Sample Contest Winner (2011)", priority: 50 }
        ]
    },
    contestants: [
        {
            name: "Alice Sample",
            cfRating: 3216,
            achievements: [
                { achievement: "ICPC World Finals Gold Medalist (2024)", priority: 104 },
                { achievement: "Sample Cup Finalist (2019, 2020, 2022-2024)", priority: 90 },
                { achievement: "ICPC finalist (2021, 2022)", priority: 80 },
                { achievement: "Sample Open 2nd (2023)", priority: 70 }
            ]
        },
        {
            name: "Bob Sample",
            cfRating: 2987,
            achievements: [ { achievement: "IOI Gold Medalist (2022)", priority: 64 } ]
        },
        { name: "Carol Sample", achievements: [] }
    ]
};

// --- helpers identical to svg/personal.svg ---
function readBlob(id, tokenName) {
    var el = document.getElementById(id);
    if (!el) return null;
    var text = el.textContent.trim();
    if (text === TOKEN(tokenName)) return null;
    try {
        return JSON.parse(text);
    } catch (e) {
        console.error("Failed to parse " + tokenName + ":", e);
        return null;
    }
}

function applyColor(styleId, tokenName, cssName, value) {
    var el = document.getElementById(styleId);
    if (el.textContent.indexOf(TOKEN(tokenName)) !== -1) {
        el.textContent = ":root { --" + cssName + ": " + value + "; }";
    }
}

function applyImage(imageId, tokenNames, dataUri) {
    var el = document.getElementById(imageId);
    var href = el.getAttribute("href");
    for (var i = 0; i < tokenNames.length; i++) {
        if (href.indexOf(TOKEN(tokenNames[i])) !== -1) {
            el.setAttribute("href", dataUri);
            return;
        }
    }
}

function formatAchievement(raw) {
    var ach = raw;
    if (ach.lastIndexOf("ICPC ", 0) === 0) {
        var c = ach.charAt(5);
        var isLowercaseLetter = c.toLowerCase() !== c.toUpperCase() && c === c.toLowerCase();
        ach = isLowercaseLetter ? "WF " + ach.slice(5) : ach.slice(5);
    }
    if (ach.length >= 29) {
        var m = ach.match(/(.*) \((.*)\)/);
        if (m) {
            var numYears = 0, tokens = 0;
            var parts = m[2].split(", ");
            for (var i = 0; i < parts.length; i++) {
                if (parts[i].indexOf("-") !== -1) {
                    var range = parts[i].split("-");
                    numYears += Number(range[1]) - Number(range[0]) + 1;
                    tokens += 2;
                } else {
                    numYears += 1;
                    tokens += 1;
                }
            }
            if (tokens > 2) ach = m[1] + " (x" + numYears + ")";
        }
    }
    return ach;
}

function fillRating(container, person, x) {
    if (person.cfRating === null || person.cfRating === undefined) {
        container.remove();
        return;
    }
    container.querySelector(".rating-pill").setAttribute("x", x);
    container.querySelector(".rating-cf").setAttribute("x", x);
    var value = container.querySelector(".rating-value tspan");
    value.setAttribute("x", x + 39);
    value.textContent = person.cfRating;
}

function fillAchievements(container, person) {
    var achievements = (person.achievements || []).slice(0, 4);
    var slots = container.querySelectorAll(".ach");
    for (var i = 0; i < slots.length; i++) {
        if (i < achievements.length) {
            slots[i].querySelector("tspan").textContent =
                formatAchievement(achievements[i].achievement);
        } else {
            slots[i].remove();
        }
    }
}

function shrinkSvgText() {
    var spans = document.getElementsByTagName("tspan");
    for (var i = 0; i < spans.length; i++) {
        var span = spans[i];
        var length = span.getAttribute("textLength");
        if (!length) continue;
        span.removeAttribute("textLength");
        span.removeAttribute("lengthAdjust");
        if (span.getBBox().width > parseFloat(length)) {
            span.setAttribute("textLength", length);
            span.setAttribute("lengthAdjust", "spacingAndGlyphs");
        }
    }
}
// --- end shared helpers ---

var renderDefaults = readBlob("render-defaults", "render.json") || {};
var cfg = Object.assign({}, BUILTIN, renderDefaults);
cfg.finals = Object.assign({}, BUILTIN.finals, renderDefaults.finals || {});
var team = readBlob("team-data", "team.json") || BUILTIN_TEAM;
var university = team.university || {};
var teamInfo = team.team || {};

// Detach the prototypes container from the DOM immediately after the
// blobs are parsed and before any scene building. cloneNode()/querySelector()
// still work on a detached subtree, so scenes build normally; but if
// anything below throws, the sample prototypes never render on screen —
// the card fails blank instead of showing built-in sample data.
var prototypes = document.getElementById("prototypes");
prototypes.remove();

applyColor("color-main", "mainColor", "main-color", cfg.mainColor);
applyColor("color-font", "fontColor", "font-color", cfg.fontColor);
applyImage("logo-image", ["Logo", "LogoExtension"],
    "data:image/" + cfg.logoExtension + ";base64," + cfg.logo);
applyImage("background-image", ["Background"],
    "data:image/svg+xml;base64," + cfg.background);

function makeTeamScene() {
    // ports src/svg.rs:102-154
    var g = prototypes.querySelector(".scene-team").cloneNode(true);
    g.querySelector(".university-name tspan").textContent = university.fullName || "";
    g.querySelector(".team-name tspan").textContent = teamInfo.name || "";
    var x = 149;
    var hashtag = g.querySelector(".hashtag");
    if (!cfg.hideHashtag && university.hashTag) {
        hashtag.querySelector("rect").setAttribute("x", x);
        hashtag.querySelector("svg").setAttribute("x", x - 0.68);
        hashtag.querySelector("svg text").textContent = university.hashTag;
        if (university.hashTag.length > 19) {
            console.warn("Long hash tag: " + team.id);
        }
        x += 129;
    } else {
        hashtag.remove();
    }
    var site = g.querySelector(".site");
    if (!cfg.hideSite && university.region) {
        site.querySelector("rect").setAttribute("x", x);
        site.querySelector("svg").setAttribute("x", x - 0.6);
        site.querySelector("svg text").textContent = university.region;
        x += 142;
    } else {
        site.remove();
    }
    var regional = g.querySelector(".regional tspan");
    regional.setAttribute("x", x);
    regional.textContent = (teamInfo.regionals && teamInfo.regionals[0]) || "";
    return g;
}

function makePersonScene(person, isCoach) {
    // ports src/svg.rs:156-246; rating x: contestants 158, coach 240
    var g = prototypes.querySelector(".scene-person").cloneNode(true);
    g.querySelector(".person-name tspan").textContent = person.name || "";
    if (!isCoach) g.querySelector(".coach-badge").remove();
    fillRating(g.querySelector(".rating"), person, isCoach ? 240 : 158);
    fillAchievements(g.querySelector(".achievements"), person);
    return g;
}

function makeFinalsScene() {
    // ports src/svg.rs:247-362
    var g = prototypes.querySelector(".scene-finals").cloneNode(true);
    var u = university;
    var appYears = u.appYears || [];
    var wins = u.winYears || [];
    var regYears = u.regYears || [];
    var gold = (u.goldYears || []).length;
    var silver = (u.silverYears || []).length;
    var bronze = (u.bronzeYears || []).length;

    g.querySelector(".finals-count").textContent =
        appYears.length > 0 ? String(appYears.length) : "1st";

    var x;
    if (gold + silver + bronze > 0) {
        g.querySelector(".medal-count-gold tspan").textContent = "x " + gold;
        g.querySelector(".medal-count-silver tspan").textContent = "x " + silver;
        g.querySelector(".medal-count-bronze tspan").textContent = "x " + bronze;
        x = 455.29;
    } else {
        g.querySelector(".medals").remove();
        x = 279;
    }

    var cupProto = g.querySelector(".cup");
    var distX = wins.length >= 5 ? 50 : 70;
    for (var i = 0; i < wins.length; i++) {
        var cup = cupProto.cloneNode(true);
        cup.querySelector(".cup-icon").setAttribute("x", x);
        var yearSpan = cup.querySelector(".cup-year");
        yearSpan.setAttribute("x", x + 18);
        yearSpan.textContent = wins[i];
        cupProto.parentNode.insertBefore(cup, cupProto);
        x += distX;
    }
    cupProto.remove();

    if (wins.length >= 5) x += 20;
    x += 20;

    var rcProto = g.querySelector(".rc");
    var rcLabels = regYears.length > 3 ? ["x " + regYears.length] : regYears.map(String);
    for (var j = 0; j < rcLabels.length; j++) {
        var rc = rcProto.cloneNode(true);
        rc.querySelector(".rc-year-box").setAttribute("x", x - 20);
        rc.querySelector(".rc-year").textContent = rcLabels[j];
        rc.querySelector(".rc-plate").setAttribute("x", x);
        var labelSpans = rc.querySelectorAll(".rc-label tspan");
        for (var k = 0; k < labelSpans.length; k++) {
            labelSpans[k].setAttribute("x", x + 10);
        }
        rcProto.parentNode.insertBefore(rc, rcProto);
        x += 100;
    }
    rcProto.remove();
    return g;
}

// scene list in display order — ports the template choice in src/svg.rs:59-83
// plus the include_finals condition in src/svg.rs:49-58
var scenes = [makeTeamScene()];
var contestants = team.contestants || [];
if (contestants.length > 3) {
    console.warn("More than 3 contestants; showing first 3");
}
for (var ci = 0; ci < Math.min(contestants.length, 3); ci++) {
    scenes.push(makePersonScene(contestants[ci], false));
}
if (team.coach) {
    scenes.push(makePersonScene(team.coach, true));
}
var includeFinals = cfg.contestType === "ICPC" && cfg.finals.include &&
    (cfg.finals.includeEmpty || (university.appYears || []).length > 0);
if (includeFinals) {
    scenes.push(makeFinalsScene());
}
scenes.push(makeTeamScene()); // resting scene, never fades

// document order is bottom-to-top: append in reverse display order
var container = document.getElementById("scenes");
for (var si = scenes.length - 1; si >= 0; si--) {
    container.appendChild(scenes[si]);
}

// fade timing: scene i disappears at 5*(i+1) seconds; last scene persists
var css = "@keyframes turn-off { 0% { opacity: 1; } 100% { opacity: 0; } }\n";
for (var ai = 0; ai < scenes.length - 1; ai++) {
    scenes[ai].setAttribute("class", "scene" + ai);
    css += ".scene" + ai + " { opacity: 0; animation: turn-off 0.5s;" +
        " animation-timing-function: ease-in-out;" +
        " animation-delay: " + 5 * (ai + 1) + "s;" +
        " animation-fill-mode: both; }\n";
}
var styleEl = document.createElementNS(SVG_NS, "style");
styleEl.textContent = css;
document.documentElement.appendChild(styleEl);

shrinkSvgText();
